// Crawlr — Mumbai bar deals + crawl planner. No build step; data lives in data/bars.json
// (generated by scripts/build_data.py from verified Google listings + scripts/curated.json).
(function () {
  "use strict";

  const DAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const DAYS_LONG = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  const $ = (id) => document.getElementById(id);
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const store = {
    get(k, d) { try { const v = localStorage.getItem(k); return v == null ? d : JSON.parse(v); } catch (e) { return d; } },
    set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }
  };

  // ---- time: a "bar day" runs 06:00 → 06:00, so 1am Saturday counts as Friday night ----
  const toMin = (s) => { const [h, m] = s.split(":").map(Number); return h * 60 + m; };
  const bd = (m) => (((m - 360) % 1440) + 1440) % 1440;          // clock minutes → bar-day minutes
  const clock = (t) => (t + 360) % 1440;                            // bar-day minutes → clock minutes
  const fmt = (m) => { m = ((m % 1440) + 1440) % 1440; let h = Math.floor(m / 60), mm = m % 60; const ap = h < 12 ? "am" : "pm"; h = h % 12 || 12; return h + (mm ? ":" + String(mm).padStart(2, "0") : "") + ap; };
  const hhmm = (m) => String(Math.floor(m / 60)).padStart(2, "0") + ":" + String(m % 60).padStart(2, "0");
  const dur = (m) => m < 60 ? m + " min" : Math.floor(m / 60) + "h" + (m % 60 ? " " + (m % 60) + "m" : "");
  const daysLabel = (d) => d.length === 7 ? "daily" : d.join() === "1,2,3,4,5" ? "Mon–Fri" : d.join() === "0,6" ? "Sat–Sun" : d.map((x) => DAYS[x]).join(", ");
  const span = (s, e) => { const a = bd(toMin(s)); let b = bd(toMin(e)); if (b <= a) b = 1440; return [a, b]; };

  function istNow() {
    const p = Object.fromEntries(new Intl.DateTimeFormat("en-GB", { timeZone: "Asia/Kolkata", weekday: "short", hour: "2-digit", minute: "2-digit", hour12: false })
      .formatToParts(new Date()).map((x) => [x.type, x.value]));
    const m = (+p.hour % 24) * 60 + +p.minute;
    let day = DAYS.indexOf(p.weekday);
    if (m < 360) day = (day + 6) % 7;
    return { day, t: bd(m) };
  }

  // Opening hours for an outlet on a bar-day, as [start, end] bar-day minutes; null when unknown.
  function hoursOn(o, day) {
    if (!o.hours || !Object.keys(o.hours).length) return null;
    const r = o.hours[day];
    if (!r) return null;
    return r.map(([s, e]) => span(s, e));
  }
  function windowStatus(wins, t) {
    for (const [s, e] of wins) if (t >= s && t < e) return { k: "on", left: e - t, s, e };
    const next = wins.filter(([s]) => s > t).sort((a, b) => a[0] - b[0])[0];
    if (next) return { k: "later", inn: next[0] - t, s: next[0], e: next[1] };
    const last = wins[wins.length - 1];
    return last ? { k: "done", s: last[0], e: last[1] } : null;
  }
  // Status of a deal at an outlet. Untimed deals return null (they're listed separately).
  function dealStatus(d, o, day, t) {
    if (d.untimed) return null;
    if (d.allDay) { const h = hoursOn(o, day); return h && h.length ? windowStatus(h, t) : null; }
    if (!d.days.includes(day)) return null;
    const h = hoursOn(o, day);
    if (h && !h.length) return null;                               // closed all day
    return windowStatus([span(d.s, d.e)], t);
  }
  const RANK = { on: 0, later: 1, done: 2 };

  function km(a, b) {
    const R = 6371, r = Math.PI / 180, dl = (b[0] - a[0]) * r, dg = (b[1] - a[1]) * r;
    const x = Math.sin(dl / 2) ** 2 + Math.cos(a[0] * r) * Math.cos(b[0] * r) * Math.sin(dg / 2) ** 2;
    return 2 * R * Math.asin(Math.sqrt(x));
  }
  // Rough Mumbai cab time: road distance ~1.4× straight line, ~18 km/h average, +5 min to find a cab.
  const cabMin = (d) => Math.round(5 + (d * 1.4) / 18 * 60);
  const kmLabel = (d) => d < 1 ? "<1 km" : d.toFixed(1) + " km";
  const mapsUrl = (b, o) => "https://www.google.com/maps/search/?api=1&query=" + encodeURIComponent(b.name + " " + o.label + " " + o.area + " Mumbai");
  const dealsFor = (b, o) => b.deals.filter((d) => !d.only || d.only.includes(o.area));
  const dealTime = (d) => d.allDay ? "Whenever it's open" : `${d.approx ? "From about " : ""}${fmt(toMin(d.s))}–${fmt(toMin(d.e))} · ${daysLabel(d.days)}`;

  // ---- state ----
  let DATA = null;
  const st = {
    live: true, day: 0, t: 0,
    area: store.get("crawlr.area", "Bandra West"),
    f: store.get("crawlr.filter", "all"),
    tab: "deals", moreOpen: 12, favs: store.get("crawlr.favs", []), favDay: "week",
    crawl: store.get("crawlr.crawl", [])       // [{bar, outlet}]
  };
  const sync = () => { if (st.live) { const n = istNow(); st.day = n.day; st.t = n.t; } };
  const here = () => DATA.areas[st.area];
  // Is this outlet in the chosen neighbourhood? "My location" means within 2 km (or more when widened).
  // extraKm > 0 also lets in outlets of other areas within that distance of the centre.
  function inArea(o, extraKm = 0) {
    if (st.area === "My location") return km(here(), o.ll) <= Math.max(2, extraKm);
    return o.area === st.area || (extraKm > 0 && km(here(), o.ll) <= extraKm);
  }
  // Closing time tonight from Google hours (bar-day minutes), or null when unknown.
  function closesAt(o, day) { const h = hoursOn(o, day); return h && h.length ? Math.max(...h.map((r) => r[1])) : null; }
  const LATE = 1140;                                                   // 1:00am in bar-day minutes
  const lateOutlet = (o) => (closesAt(o, st.day) || 0) >= LATE;
  const passes = (d, o) => st.f === "all" || (st.f === "late" ? (o ? lateOutlet(o) : false) || (d.tags || []).includes("late") : (d.tags || []).includes(st.f));
  const inCrawl = (id) => st.crawl.some((c) => c.bar === id);
  const isFav = (id) => st.favs.includes(id);

  // ---- deals view ----
  function collect() {
    const timed = [], untimed = [], dealOutletKeys = new Set();
    for (const b of DATA.bars) {
      let best = null, bestU = null;
      b.outlets.forEach((o, oi) => {
        if (!inArea(o, st.wide ? 3 : 0)) return;
        const dist = km(here(), o.ll);
        for (const d of dealsFor(b, o)) {
          if (!passes(d, o)) continue;
          if (d.untimed) {
            const h = hoursOn(o, st.day);
            if (h && !h.length) continue;
            if (!bestU || dist < bestU.dist) bestU = { b, o, oi, d, dist };
            continue;
          }
          const s = dealStatus(d, o, st.day, st.t); if (!s) continue;
          const c = { b, o, oi, d, s, dist };
          if (!best || RANK[s.k] < RANK[best.s.k] ||
            (RANK[s.k] === RANK[best.s.k] && (s.k === "later" ? (s.inn < best.s.inn || (s.inn === best.s.inn && dist < best.dist)) : dist < best.dist))) best = c;
        }
      });
      if (best) { timed.push(best); dealOutletKeys.add(b.id); }
      else if (bestU) { untimed.push(bestU); dealOutletKeys.add(b.id); }
    }
    // Bars with no listed deal that are open at this time.
    const open = [];
    for (const b of DATA.bars) {
      if (dealOutletKeys.has(b.id)) continue;
      let best = null;
      b.outlets.forEach((o, oi) => {
        if (!inArea(o, st.wide ? 3 : 0)) return;
        const h = hoursOn(o, st.day); if (!h) return;
        if (st.f === "late" && !lateOutlet(o)) return;
        const s = windowStatus(h, st.t); if (!s || s.k !== "on") return;
        const dist = km(here(), o.ll);
        if (!best || dist < best.dist) best = { b, o, oi, s, dist };
      });
      if (best) open.push(best);
    }
    timed.sort((a, b) => RANK[a.s.k] - RANK[b.s.k] || (a.s.k === "later" ? a.s.inn - b.s.inn : 0) || a.dist - b.dist);
    untimed.sort((a, b) => a.dist - b.dist);
    open.sort((a, b) => a.dist - b.dist);
    return { timed, untimed, open };
  }

  // ---- icons ----
  const ico = (id, cls = "i") => `<svg class="${cls}" aria-hidden="true"><use href="#i-${id}"/></svg>`;
  function drinkIcon(d) {
    const t = d ? (d.text || "").toLowerCase() : "";
    if (/tequila|shot/.test(t)) return "shot";
    if (/beer|pint|brew|taster|bucket|pitcher/.test(t)) return "beer";
    if (/wine|sangria/.test(t)) return "wine";
    if (/cocktail|liit|martini/.test(t)) return "cocktail";
    if (d && (d.tags || []).includes("2for1")) return "cheers";
    if (d && (d.tags || []).includes("perk")) return "spark";
    return "glasses";
  }

  function renderDeals() {
    const { timed, untimed, open } = collect();
    const on = timed.filter((r) => r.s.k === "on"), later = timed.filter((r) => r.s.k === "later"), done = timed.filter((r) => r.s.k === "done");
    const areaName = st.area === "My location" ? "Near you" : st.area;
    $("summary").innerHTML = `<span class="where">${ico("pin")}<b>${esc(areaName)}</b></span><span><span class="dot"></span><b>${on.length}</b> on now</span>` +
      (later.length ? `<span><b>${later.length}</b> later</span>` : "") +
      (st.f === "all" ? `<span><b>${open.length}</b> other bars open</span>` : "");
    const sect = (title, list, fn) => list.length ? `<div class="group">${title}<span class="n">${list.length}</span></div><div class="list">${list.map(fn).join("")}</div>` : "";
    const showOpen = st.f === "all" || st.f === "late";
    const shownOpen = open.slice(0, st.moreOpen);
    $("list").innerHTML =
      (sect("On now", on, card) + sect("Later", later, card) +
      sect("Times not listed", untimed, cardU) +
      sect("Done for today", done, card) +
      (showOpen ? sect("Also open", shownOpen, rowOpen) +
        (open.length > st.moreOpen ? `<button class="more" type="button" id="moreOpen">Show more</button>` : "") : "")) ||
      `<div class="empty">${ico("glasses")}Nothing in ${esc(areaName)} right now.</div>`;
    $("list").insertAdjacentHTML("beforeend", `<button class="more wide" type="button" id="wideBtn">${ico(st.wide ? "x" : "plus")}${st.wide ? `Only ${esc(areaName)}` : "Include nearby areas (3 km)"}</button>`);
  }

  const pct = (m) => (m / 1440 * 100).toFixed(2) + "%";
  const addBtn = (b, oi) => inCrawl(b.id)
    ? `<button class="btn" type="button" data-add="${b.id}" data-o="${oi}" aria-pressed="true">${ico("check")}In crawl</button>`
    : `<button class="btn fill" type="button" data-add="${b.id}" data-o="${oi}" aria-pressed="false">${ico("plus")}Crawl</button>`;
  const favBtn = (b) => `<button class="btn icon fav ${isFav(b.id) ? "on" : ""}" type="button" data-fav="${b.id}" aria-pressed="${isFav(b.id)}" aria-label="${isFav(b.id) ? "Remove from" : "Add to"} favourites">${ico("heart")}</button>`;
  const mapBtn = (b, o) => `<a class="btn icon" href="${mapsUrl(b, o)}" target="_blank" rel="noopener" title="Open in Maps" aria-label="Open ${esc(b.name)} in Maps">${ico("map")}</a>`;
  const srcFlag = (d) => `<span class="flag src" title="${d.conf === "recent" ? "Seen recently" : "Older report"}: ${esc(d.src)}${d.note ? ". " + esc(d.note) : ""}">${ico("info")}${d.conf === "recent" ? "Recent" : "Older"}</span>`;
  const warnFlag = (o) => o.status !== "open" ? `<span class="flag warn" title="Opening hours aren't listed on Google">${ico("warn")}Call first</span>` : "";
  const sub = (o, dist) => { const c = closesAt(o, st.day); return `<div class="sub">${ico("pin")}${esc(o.area)} · ${kmLabel(dist)}${c ? ` · open till ${fmt(clock(c % 1440))}` : ""}</div>`; };
  function outletsBlock(b) {
    if (b.outlets.length < 2) return "";
    return `<details class="outs"><summary>${ico("store")}${b.outlets.length} outlets</summary><ul>${
      b.outlets.map((x) => ({ x, d: km(here(), x.ll) })).sort((p, q) => p.d - q.d)
        .map(({ x, d }) => `<li class="${inArea(x) ? "here" : ""}"><span>${esc(x.area)} · ${esc(x.label)}</span><span class="r">${x.status !== "open" ? ico("warn") : ""}${kmLabel(d)}<a href="${mapsUrl(b, x)}" target="_blank" rel="noopener" aria-label="Map">${ico("map")}</a></span></li>`).join("")
    }</ul></details>`;
  }
  function card({ b, o, oi, d, s, dist }) {
    const lab = s.k === "on" ? `${dur(s.left)} left` : s.k === "later" ? `in ${dur(s.inn)}` : "Over";
    return `<article class="card ${s.k === "on" ? "on" : s.k === "done" ? "past" : ""}">
      <div class="tile">${ico(drinkIcon(d))}</div>
      <div><div class="name">${esc(b.name)}</div>${sub(o, dist)}</div>
      <span class="pill ${s.k}">${lab}</span>
      <div class="deal">${esc(d.text)}</div>
      <div class="meta">${ico("clock")}${dealTime(d)}</div>
      <div class="bar" aria-hidden="true"><i style="left:${pct(s.s)};width:${pct(s.e - s.s)}"></i><b style="left:${pct(st.t)}"></b></div>
      <div class="acts">${addBtn(b, oi)}${favBtn(b)}${b.outlets.length > 1 ? "" : mapBtn(b, o)}${srcFlag(d)}${warnFlag(o)}</div>
      ${outletsBlock(b)}
    </article>`;
  }
  function cardU({ b, o, oi, d, dist }) {
    return `<article class="card">
      <div class="tile">${ico(drinkIcon(d))}</div>
      <div><div class="name">${esc(b.name)}</div>${sub(o, dist)}</div>
      <span class="pill quiet">Ask</span>
      <div class="deal">${esc(d.text)}</div>
      <div class="acts">${addBtn(b, oi)}${favBtn(b)}${b.outlets.length > 1 ? "" : mapBtn(b, o)}${srcFlag(d)}</div>
      ${outletsBlock(b)}
    </article>`;
  }
  function rowOpen({ b, o, oi, s, dist }) {
    return `<div class="mini">
      <div class="tile">${ico("glasses")}</div>
      <div><div class="name">${esc(b.name)}</div>${sub(o, dist)}</div>
      <span class="till">${ico("moon")}${fmt(clock(s.e % 1440))}</span>
      ${favBtn(b)}
      ${inCrawl(b.id)
        ? `<button class="btn icon" type="button" data-add="${b.id}" data-o="${oi}" aria-pressed="true" aria-label="Remove from crawl">${ico("check")}</button>`
        : `<button class="btn icon" type="button" data-add="${b.id}" data-o="${oi}" aria-pressed="false" aria-label="Add to crawl">${ico("plus")}</button>`}
    </div>`;
  }

  // ---- favourites: your saved bars and their deals across the week ----
  const WEEK = [1, 2, 3, 4, 5, 6, 0];
  function favDealsOn(b, day) {
    const out = [];
    for (const d of b.deals) {
      if (d.untimed) continue;
      const outs = b.outlets.filter((o) => (!d.only || d.only.includes(o.area)));
      if (!outs.length) continue;
      if (d.allDay) {
        const open = outs.map((o) => hoursOn(o, day)).filter((h) => h && h.length);
        if (open.length) out.push({ d, outs, time: "Whenever open" });
      } else if (d.days.includes(day)) out.push({ d, outs, time: `${d.approx ? "~" : ""}${fmt(toMin(d.s))}–${fmt(toMin(d.e))}`, s: toMin(d.s) });
    }
    return out;
  }
  function renderFavs() {
    const bars = DATA.bars.filter((b) => isFav(b.id));
    $("favDays").innerHTML = [["week", "Week"], ...WEEK.map((d) => [String(d), DAYS[d]])]
      .map(([v, l]) => `<button class="chip ${v === String(istNow().day) ? "today" : ""}" type="button" data-fd="${v}" aria-pressed="${st.favDay === v}">${l}</button>`).join("");
    if (!bars.length) {
      $("favOut").innerHTML = `<div class="empty">${ico("heart")}Tap the heart on any bar to save it here.</div>`; return;
    }
    const nearest = (outs) => outs.map((o) => ({ o, d: km(here(), o.ll) })).sort((a, b) => a.d - b.d)[0];
    const row = (b, x) => { const n = nearest(x.outs); return `<div class="fdeal">
        <div class="tile">${ico(drinkIcon(x.d))}</div>
        <div><div class="name">${esc(b.name)}</div><div class="sub">${esc(x.d.text)}</div></div>
        <div class="ftime">${x.time}<small>${esc(n.o.area)}${x.outs.length > 1 ? ` +${x.outs.length - 1}` : ""}</small></div>
      </div>`; };
    const days = st.favDay === "week" ? WEEK : [+st.favDay];
    const today = istNow().day;
    let html = days.map((day) => {
      const items = [];
      for (const b of bars) for (const x of favDealsOn(b, day)) items.push([b, x]);
      items.sort((a, b) => (a[1].s ?? 9999) - (b[1].s ?? 9999));
      return `<div class="group">${DAYS_LONG[day]}${day === today ? ` <span class="todaytag">today</span>` : ""}<span class="n">${items.length}</span></div>` +
        (items.length ? `<div class="list">${items.map(([b, x]) => row(b, x)).join("")}</div>` : `<p class="nodeal">No deals at your favourites.</p>`);
    }).join("");
    const untimed = bars.flatMap((b) => b.deals.filter((d) => d.untimed).map((d) => [b, d]));
    if (untimed.length) html += `<div class="group">Any day · times not listed<span class="n">${untimed.length}</span></div><div class="list">${untimed.map(([b, d]) => row(b, { d, outs: b.outlets.filter((o) => !d.only || d.only.includes(o.area)), time: "Ask" })).join("")}</div>`;
    const none = bars.filter((b) => !b.deals.length);
    if (none.length) html += `<div class="group">No deals listed<span class="n">${none.length}</span></div>` + none.map((b) => `<div class="mini"><div class="tile">${ico("glasses")}</div><div><div class="name">${esc(b.name)}</div></div><span></span>${favBtn(b)}</div>`).join("");
    html += `<div class="group">Saved<span class="n">${bars.length}</span></div><div class="favlist">${bars.map((b) => `<span class="favchip">${esc(b.name)}<button type="button" data-fav="${b.id}" aria-label="Remove ${esc(b.name)}">${ico("x")}</button></span>`).join("")}</div>`;
    $("favOut").innerHTML = html;
  }

  // ---- crawl ----
  // Plan a crawl around the chosen area.
  // - Bars you've already added are always kept (they're "pinned").
  // - Only bars within opts.radius km of the area centre are considered, so the night stays in one neighbourhood.
  // - At each step it picks the best next stop by: travel time + waiting for a deal to start + distance from the
  //   area centre, with small penalties for weaker options (a perk, a deal with no published times, or no deal).
  const walkMin = (d) => Math.round((d * 1.3) / 4.5 * 60);          // ~4.5 km/h, streets ~1.3× straight line
  const hop = (d) => d <= 0.9 ? { mins: walkMin(d), walk: true } : { mins: cabMin(d), walk: false };
  function planCrawl(n, stay, opts) {
    const centre = DATA.areas[st.area];
    const pinned = new Map((opts.keep || []).map((c) => [c.bar, c.outlet]));
    n = Math.max(n, pinned.size);
    let pos = centre, t = st.t;
    const used = new Set(), stops = [];
    for (let i = 0; i < n; i++) {
      let best = null;
      const consider = (c) => { if (!best || c.score < best.score) best = c; };
      const pinsLeft = [...pinned.keys()].filter((id) => !used.has(id)).length;
      const mustPin = n - i <= pinsLeft;                              // remaining slots are only enough for your picks
      for (const b of DATA.bars) {
        if (used.has(b.id)) continue;
        const isPinned = pinned.has(b.id);
        if (mustPin && !isPinned) continue;
        b.outlets.forEach((o, oi) => {
          if (isPinned && pinned.get(b.id) !== oi) return;
          const fromCentre = km(centre, o.ll);
          if (!isPinned && !inArea(o, opts.radius)) return;
          if (!isPinned && o.status !== "open" && !opts.unconfirmed) return;
          const dist = km(pos, o.ll), h1 = i === 0 && dist < 0.3 ? { mins: 0, walk: true } : hop(dist), arrive = t + h1.mins;
          const h = hoursOn(o, st.day);
          const openAt = (m) => !h || h.some(([s, e]) => m >= s && m < e);
          const base = { b, o, oi, dist, travel: h1.mins, walk: h1.walk, arrive, pinned: isPinned };
          const pinBonus = isPinned ? -20 : 0;
          let had = false;
          for (const d of dealsFor(b, o)) {
            if (!passes(d, o) && !isPinned) continue;
            if (d.untimed) {
              if (!openAt(arrive)) continue;
              had = true;
              consider({ ...base, d, start: arrive, score: h1.mins + 1.5 * fromCentre + 8 + pinBonus });
              continue;
            }
            const s = dealStatus(d, o, st.day, arrive); if (!s || s.k === "done") continue;
            const wait = s.k === "later" ? s.inn : 0;
            if (wait > 45) continue;
            if (s.k === "on" && s.left < 20) continue;
            if (!openAt(arrive + wait)) continue;
            had = true;
            const perk = (d.tags || []).includes("perk") ? 8 : 0;
            consider({ ...base, d, start: arrive + wait, score: h1.mins + 1.5 * wait + 1.5 * fromCentre + perk + pinBonus });
          }
          if (!had && (opts.fill || isPinned) && openAt(arrive)) {
            consider({ ...base, d: dealsFor(b, o)[0] || null, start: arrive, score: h1.mins + 1.5 * fromCentre + 15 + pinBonus });
          }
        });
      }
      if (!best) break;
      used.add(best.b.id); stops.push(best);
      pos = best.o.ll; t = best.start + stay;
      if (t >= 1440) break;
    }
    return stops;
  }

  // Lay out the crawl in its saved order, starting from the chosen area.
  function pickOf(c) {
    const b = DATA.bars.find((x) => x.id === c.bar); if (!b) return null;
    const o = b.outlets[c.outlet] || b.outlets[0];
    const ds = dealsFor(b, o).filter((d) => !d.untimed);
    return { b, o, oi: b.outlets.indexOf(o), deals: ds, d: ds[0] || dealsFor(b, o)[0] || null };
  }
  function simulate(picks, stay) {
    let pos = DATA.areas[st.area], t = st.t, cost = 0, travelTotal = 0;
    const out = picks.map((p) => {
      const dist = km(pos, p.o.ll), h1 = hop(dist), arrive = t + h1.mins;
      // use whichever of this bar's deals is best at arrival time
      let d = p.d, wait = 0, miss = p.deals.length > 0;
      for (const x of p.deals) {
        const s = dealStatus(x, p.o, st.day, arrive);
        if (s && s.k === "on") { d = x; wait = 0; miss = false; break; }
        if (s && s.k === "later" && s.inn <= 60) { d = x; wait = s.inn; miss = false; }
      }
      const h = hoursOn(p.o, st.day);
      const closed = h && !h.some(([a2, e]) => arrive + wait >= a2 && arrive + wait < e);
      const start = arrive + wait;
      cost += h1.mins + wait + (miss ? 45 : 0) + (closed ? 90 : 0);
      travelTotal += h1.mins;
      pos = p.o.ll; t = start + stay;
      return { ...p, d, dist, travel: h1.mins, walk: h1.walk, arrive, start };
    });
    return { stops: out, cost, travelTotal };
  }
  function layoutManual(stay) {
    return simulate(st.crawl.map(pickOf).filter(Boolean), stay).stops;
  }
  // Try every order (up to 7 stops) and keep the one with the least travel, waiting and missed deals.
  function optimizeCrawl(stay) {
    const picks = st.crawl.map(pickOf).filter(Boolean);
    if (picks.length < 2) return null;
    const before = simulate(picks, stay);
    let best = before, bestOrder = picks;
    const perm = (arr, k = 0) => {
      if (k === arr.length) { const r = simulate(arr, stay); if (r.cost < best.cost) { best = r; bestOrder = arr.slice(); } return; }
      for (let i = k; i < arr.length; i++) { [arr[k], arr[i]] = [arr[i], arr[k]]; perm(arr, k + 1); [arr[k], arr[i]] = [arr[i], arr[k]]; }
    };
    if (picks.length <= 7) perm(picks.slice());
    st.crawl = bestOrder.map((p) => ({ bar: p.b.id, outlet: p.oi }));
    store.set("crawlr.crawl", st.crawl);
    return { saved: before.travelTotal - best.travelTotal, changed: bestOrder !== picks && best !== before };
  }

  function renderCrawl(stops, auto) {
    $("crawlCount").textContent = st.crawl.length || "";
    const out = $("crawlOut");
    if (!stops.length) {
      out.innerHTML = auto
        ? `<div class="empty">${ico("moon")}No deals near ${esc(st.area)} around ${fmt(clock(st.t))}. Try earlier, or switch on Fill gaps.</div>`
        : `<div class="empty">${ico("route")}Plan a crawl, or tap Crawl on any bar.</div>`;
      return;
    }
    const stay = +$("stay").value;
    const pts = [DATA.areas[st.area], ...stops.map((s) => s.o.ll)].map((p) => p.join(","));
    const route = "https://www.google.com/maps/dir/?api=1&travelmode=driving&origin=" + pts[0] + "&destination=" + pts[pts.length - 1] +
      (pts.length > 2 ? "&waypoints=" + encodeURIComponent(pts.slice(1, -1).join("|")) : "");
    const end = stops[stops.length - 1].start + stay;
    out.innerHTML = `<ol class="stops">${stops.map((s, i) => {
      const ds = s.d ? dealStatus(s.d, s.o, st.day, s.start) : null;
      const h = hoursOn(s.o, st.day);
      const closed = h && !h.some(([a, e]) => s.start >= a && s.start < e);
      const warn = closed ? "Closed by then" : s.d && !s.d.untimed && !s.d.allDay && (!ds || ds.k === "done") ? "Deal over by then" : "";
      return `<li class="stop">
        <div class="hop">${ico(s.walk ? "walk" : "car")}${s.travel ? `${s.travel} min ${s.walk ? "walk" : "cab"} · ${kmLabel(s.dist)}` : i === 0 ? "Start here" : "Next door"}</div>
        <div class="when">${fmt(clock(s.start))}</div>
        <article class="card ${s.d ? "on" : ""}" data-n="${i + 1}">
          <div class="tile">${ico(drinkIcon(s.d))}</div>
          <div><div class="name">${esc(s.b.name)}</div>${sub(s.o, s.dist)}</div>
          <button class="btn icon" type="button" data-rm="${s.b.id}" aria-label="Remove ${esc(s.b.name)}">${ico("x")}</button>
          <div class="deal">${s.d ? esc(s.d.text) : `<span class="flag">No deal listed</span>`}</div>
          ${warn ? `<div class="meta flag warn">${ico("warn")}${warn}</div>` : s.d && !s.d.untimed ? `<div class="meta">${ico("clock")}${dealTime(s.d)}</div>` : ""}
          ${s.o.status !== "open" ? `<div class="meta flag warn">${ico("warn")}Call first</div>` : ""}
        </article>
      </li>`; }).join("")}</ol>
      <p class="note">${ico("clock")}${fmt(clock(stops[0].start))} – ${fmt(clock(end))} · ${stops.length} stops</p>
      <div class="crawlacts">
        ${stops.length > 1 ? `<button class="go ghost" type="button" id="optBtn">${ico("spark")}Optimize route</button>` : ""}
        <a class="route" href="${route}" target="_blank" rel="noopener">${ico("map")}Open in Maps</a>
      </div>
      ${st.optMsg ? `<p class="note">${ico("check")}${st.optMsg}</p>` : ""}`;
    st.optMsg = "";
  }

  function showCrawl(auto) {
    const stay = +$("stay").value;
    if (auto) {
      const stops = planCrawl(+$("stops").value, stay, { unconfirmed: $("incUnconf").checked, fill: $("fill").checked, radius: +$("radius").value, keep: st.crawl });
      st.crawl = stops.map((s) => ({ bar: s.b.id, outlet: s.oi }));
      store.set("crawlr.crawl", st.crawl);
      renderCrawl(stops, true);
    } else renderCrawl(layoutManual(stay), false);
  }

  // ---- your location ----
  const ME = "My location", MUMBAI = [19.07, 72.88];
  function setMe(ll) {
    DATA.areas[ME] = ll; st.area = ME; store.set("crawlr.area", ME);
    store.set("crawlr.loc", { ll, ts: Date.now() });
  }
  function useMyLocation() {
    const msg = (t) => { $("locMsg").textContent = t; $("locMsg").hidden = !t; };
    store.set("crawlr.asked", 1); $("locPrompt").hidden = true;
    if (!navigator.geolocation) { msg("Location isn't available in this browser. Pick an area instead."); return; }
    msg("Finding you…");
    navigator.geolocation.getCurrentPosition((pos) => {
      const ll = [pos.coords.latitude, pos.coords.longitude];
      if (km(ll, MUMBAI) > 60) { msg("You look to be outside Mumbai. Pick an area instead."); return; }
      msg(""); setMe(ll); st.moreOpen = 12; renderAreas(); render();
    }, (err) => {
      msg(err.code === 1 ? "Location is blocked for this site. Allow it in your browser, or pick an area." : "Couldn't get your location. Pick an area instead.");
    }, { enableHighAccuracy: true, timeout: 10000, maximumAge: 120000 });
  }

  // ---- area tiles: every area, busiest first, each with its own warm gradient ----
  const GRADS = [["#7A3E12","#E39B3B"],["#5B1F2A","#C2525E"],["#2F3B1A","#A3A13C"],["#4A2A12","#C7773A"],["#3B1F3F","#B0587E"],["#1F3138","#3E8C8C"],["#3D2B13","#D8B25A"],["#4B1714","#D4633C"]];
  const AREA_ICONS = ["beer", "wine", "cocktail", "cheers", "shot", "glasses"];
  function renderAreas() {
    const counts = {};
    for (const b of DATA.bars) for (const o of b.outlets) counts[o.area] = (counts[o.area] || 0) + 1;
    const names = Object.keys(DATA.areas).filter((a) => counts[a]).sort((a, b) => (a === st.area ? -1 : b === st.area ? 1 : counts[b] - counts[a]));
    const meOn = st.area === ME && DATA.areas[ME];
    const nearby = meOn ? DATA.bars.reduce((n, b) => n + b.outlets.filter((o) => km(DATA.areas[ME], o.ll) <= 2).length, 0) : 0;
    const meTile = `<button class="area me" type="button" role="radio" data-me="1" aria-checked="${!!meOn}">${ico("pin")}<b>Near me</b><small>${meOn ? `${nearby} bars within 2 km` : "Use my location"}</small></button>`;
    $("areas").innerHTML = meTile + names.map((a, i) => {
      let h = 0; for (const c of a) h = (h * 31 + c.charCodeAt(0)) >>> 0;
      const [g1, g2] = GRADS[h % GRADS.length];
      return `<button class="area" type="button" role="radio" data-area="${esc(a)}" aria-checked="${a === st.area}" style="--g:linear-gradient(135deg,${g1},${g2})">
        ${ico(AREA_ICONS[h % AREA_ICONS.length])}<b>${esc(a)}</b><small>${counts[a]} bars</small></button>`;
    }).join("");
    $("areas").scrollLeft = 0;
  }

  // ---- controls ----
  function render() {
    sync();
    $("day").value = st.day;
    $("time").value = hhmm(clock(st.t));
    $("nowBtn").hidden = st.live;
    document.querySelectorAll("[data-f]").forEach((b) => b.setAttribute("aria-pressed", b.dataset.f === st.f));
    const isDeals = st.tab === "deals";
    for (const [tab, sec] of [["tabDeals", "deals"], ["tabCrawl", "crawl"], ["tabFavs", "favs"]]) {
      $(tab).setAttribute("aria-selected", st.tab === sec); $(sec).hidden = st.tab !== sec;
    }
    document.body.dataset.tab = st.tab;
    $("favCount").textContent = st.favs.length || "";
    const pins = st.crawl.length;
    $("startLbl").textContent = st.area === ME ? "Starting from you" : `Start: ${st.area}`;
    const rad = +$("radius").value;
    $("planHint").textContent = `Starts ${st.area === ME ? "where you are" : "in " + st.area} at ${fmt(clock(st.t))}, ${rad ? `stays within ${rad} km` : st.area === ME ? "stays within 2 km" : `only ${st.area} bars`}${pins ? `, keeps your ${pins} pick${pins > 1 ? "s" : ""}` : ""}.`;
    if (isDeals) renderDeals(); else if (st.tab === "favs") renderFavs(); else showCrawl(false);
    $("crawlCount").textContent = st.crawl.length || "";
  }

  function wire() {
    $("day").innerHTML = [1, 2, 3, 4, 5, 6, 0].map((d) => `<option value="${d}">${DAYS_LONG[d]}</option>`).join("");
    const saved = store.get("crawlr.loc", null);
    if (st.area === ME && saved && Date.now() - saved.ts < 6 * 3600e3) DATA.areas[ME] = saved.ll;
    if (!DATA.areas[st.area]) st.area = "Bandra West";
    renderAreas();
    if (!store.get("crawlr.asked", null)) $("locPrompt").hidden = false;
    $("locYes").addEventListener("click", useMyLocation);
    $("locNo").addEventListener("click", () => { store.set("crawlr.asked", 1); $("locPrompt").hidden = true; $("areas").scrollIntoView({ behavior: "smooth", block: "center" }); });
    $("startBtn").addEventListener("click", useMyLocation);
    $("day").addEventListener("change", (e) => { st.live = false; st.day = +e.target.value; render(); });
    $("time").addEventListener("change", (e) => { if (!e.target.value) return; st.live = false; st.t = bd(toMin(e.target.value)); render(); });
    $("nowBtn").addEventListener("click", () => { st.live = true; render(); });
    $("areas").addEventListener("click", (e) => {
      if (e.target.closest("[data-me]")) { useMyLocation(); return; }
      const t = e.target.closest("[data-area]"); if (!t) return;
      st.area = t.dataset.area; store.set("crawlr.area", st.area); st.moreOpen = 12; st.wide = false; renderAreas(); render();
    });
    document.querySelectorAll("[data-f]").forEach((b) => b.addEventListener("click", () => { st.f = b.dataset.f; store.set("crawlr.filter", st.f); render(); }));
    $("tabDeals").addEventListener("click", () => { st.tab = "deals"; render(); });
    $("tabCrawl").addEventListener("click", () => { st.tab = "crawl"; render(); });
    $("tabFavs").addEventListener("click", () => { st.tab = "favs"; render(); });
    $("planBtn").addEventListener("click", () => showCrawl(true));
    $("stay").addEventListener("change", () => showCrawl(false));
    $("radius").addEventListener("change", () => render());
    document.addEventListener("click", (e) => {
      const add = e.target.closest("[data-add]");
      if (add) {
        const id = add.dataset.add, i = st.crawl.findIndex((c) => c.bar === id);
        if (i >= 0) st.crawl.splice(i, 1); else st.crawl.push({ bar: id, outlet: +add.dataset.o });
        store.set("crawlr.crawl", st.crawl); render(); return;
      }
      const rm = e.target.closest("[data-rm]");
      if (rm) { st.crawl = st.crawl.filter((c) => c.bar !== rm.dataset.rm); store.set("crawlr.crawl", st.crawl); render(); return; }
      if (e.target.id === "moreOpen") { st.moreOpen += 20; render(); return; }
      const fv = e.target.closest("[data-fav]");
      if (fv) {
        const id = fv.dataset.fav;
        st.favs = isFav(id) ? st.favs.filter((x) => x !== id) : [...st.favs, id];
        store.set("crawlr.favs", st.favs); render(); return;
      }
      const fd = e.target.closest("[data-fd]");
      if (fd) { st.favDay = fd.dataset.fd; renderFavs(); return; }
      if (e.target.closest("#wideBtn")) { st.wide = !st.wide; st.moreOpen = 12; render(); return; }
      if (e.target.closest("#optBtn")) {
        const r = optimizeCrawl(+$("stay").value);
        st.optMsg = !r || !r.changed ? "Already the best order." : r.saved > 0 ? `Reordered. About ${r.saved} min less travel.` : "Reordered so you catch more deals.";
        showCrawl(false);
      }
    });
    setInterval(() => { if (st.live) render(); }, 60000);
  }

  // Node test hook; in the browser, load data and boot.
  if (typeof module !== "undefined") {
    module.exports = { bd, clock, dealStatus, hoursOn,
      setup: (d, s) => { DATA = d; Object.assign(st, s); },
      planCrawl: (n, stay, opts) => planCrawl(n, stay, Object.assign({ radius: 0 }, opts)), collect: () => collect(),
      favs: (ids, day) => { st.favs = ids; st.favDay = day; return DATA.bars.filter((b) => ids.includes(b.id)).map((b) => [b.name, WEEK.map((d) => favDealsOn(b, d).length)]); },
      optimize: (crawl, stay) => { st.crawl = crawl; const r = optimizeCrawl(stay); return { r, crawl: st.crawl, stops: layoutManual(stay) }; } };
    return;
  }
  fetch("data/bars.json").then((r) => r.json()).then((d) => {
    DATA = d;
    $("updated").textContent = "Bar list last checked " + new Date(d.updated).toLocaleDateString("en-IN", { day: "numeric", month: "long", year: "numeric" }) + ".";
    wire(); render();
  }).catch(() => { $("summary").textContent = "Couldn't load the bar list. Refresh to try again."; });
})();
